/**
 * MetaWorld 2.0 — WorldLens Interactive 3D World Viewer (public/metaworld.js)
 *
 * Renders all 5 neural & procedural 3D layers generated by `src/tools/meta_world_2_pipeline.py`:
 *   1. 3D Gaussian Splat Cloud (`world_3dgs.splat`, 27,264 MaskGaussian-pruned splats)
 *   2. Meta VGGT-1B Neural 3D Relief Surface (`vggt_surface.glb`, 11,008v / 21,590f)
 *   3. Meta SceneScript CSG + WFC Architecture (`collision_proxy.glb` + `wfc_courtyard_addon.glb`)
 *      with 1K ambientCG normal-mapped stone/tile floor & walls
 *   4. SAM 3.1 Semantic 3D Landmarks (`objects.json`, 5 real Polyhaven photogrammetry + 20-bone Agatha GLBs)
 *      with toggleable 3D semantic wireframe bounding boxes & standoff rings
 *   5. WorldNav 24x24m BFS-Verified NavMesh & 5 Trajectory Spline Ribbons (`navmesh.json`)
 *
 * Strictly CSP-safe (`script-src 'self'`), zero inline scripts or event handlers.
 */
(function () {
  "use strict";

  var state = {
    ready: false,
    splats: 0,
    vggtMeshLoaded: false,
    csgLoaded: false,
    wfcLoaded: false,
    landmarksLoaded: 0,
    trajectories: 0,
    depthBackend: "",
    ransacAlignment: null,
    cameraMode: "Free",
    layers: {
      splats: true,
      vggt: true,
      csg: true,
      landmarks: true,
      navmesh: false,
      bboxes: false,
    },
    errors: [],
  };
  window.__METAWORLD_STATE__ = state;

  var canvas = document.getElementById("mw-canvas");
  if (!canvas || !window.THREE) {
    state.errors.push("Missing #mw-canvas or window.THREE");
    return;
  }
  var THREE = window.THREE;
  var WorldRealism = window.WorldRealism || null;

  var statusTextEl = document.getElementById("mw-status-text");
  var poseReadoutEl = document.getElementById("mw-pose-readout");
  var statSplatsEl = document.getElementById("mw-stat-splats");
  var statVggtEl = document.getElementById("mw-stat-vggt");
  var statCsgEl = document.getElementById("mw-stat-csg");
  var statLandmarksEl = document.getElementById("mw-stat-landmarks");
  var statBfsEl = document.getElementById("mw-stat-bfs");
  var depthBadgeEl = document.getElementById("mw-depth-badge");
  var metaS3SubEl = document.getElementById("mw-meta-s3-sub");
  var metaS4El = document.getElementById("mw-meta-s4");
  var minimapCanvas = document.getElementById("mw-navmesh-minimap");
  var inspectorEl = document.getElementById("mw-inspector");
  var toggleInspectorBtn = document.getElementById("mw-toggle-inspector");

  function setStatus(msg) {
    if (statusTextEl) statusTextEl.textContent = msg;
  }

  function checkAllReady() {
    if (
      state.splats > 20000 &&
      state.vggtMeshLoaded &&
      state.csgLoaded &&
      state.landmarksLoaded >= 5 &&
      state.trajectories >= 5
    ) {
      state.ready = true;
      setStatus(
        "WorldLens Ready · " +
          state.splats.toLocaleString() +
          " 3DGS + VGGT-1B + CSG + " +
          state.landmarksLoaded +
          "/5 GLBs + " +
          state.trajectories +
          " Paths",
      );
    }
  }

  // --- Renderer, Scene, Camera ---
  var renderer = new THREE.WebGLRenderer({
    canvas: canvas,
    antialias: true,
    powerPreference: "high-performance",
  });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(
    canvas.clientWidth || window.innerWidth,
    canvas.clientHeight || window.innerHeight - 46,
  );
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 0.98;
  if (renderer.shadowMap) {
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  }

  var scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070b14);
  scene.fog = new THREE.FogExp2(0x070b14, 0.012);

  var camera = new THREE.PerspectiveCamera(
    60,
    (canvas.clientWidth || window.innerWidth) /
      Math.max(1, canvas.clientHeight || window.innerHeight - 46),
    0.1,
    450,
  );

  // Dedicated toggleable 3D Layer Groups
  var groups = {
    splats: new THREE.Group(),
    vggt: new THREE.Group(),
    csg: new THREE.Group(),
    landmarks: new THREE.Group(),
    navmesh: new THREE.Group(),
    bboxes: new THREE.Group(),
  };
  groups.splats.name = "Layer1_3DGS_Splats";
  groups.vggt.name = "Layer2_VGGT1B_Surface";
  groups.csg.name = "Layer3_SceneScript_CSG_WFC";
  groups.landmarks.name = "Layer4_SAM31_Photogrammetry_Landmarks";
  groups.navmesh.name = "Layer5_WorldNav_NavMesh_Trajectories";
  groups.bboxes.name = "Layer4b_SAM31_Semantic_Wireframes";

  scene.add(groups.splats);
  scene.add(groups.vggt);
  scene.add(groups.csg);
  scene.add(groups.landmarks);
  groups.navmesh.visible = false;
  groups.bboxes.visible = false;
  scene.add(groups.navmesh);
  scene.add(groups.bboxes);

  // --- Lighting setup ---
  var ambientLight = new THREE.AmbientLight(0x7c93b8, 0.85);
  scene.add(ambientLight);

  var hemiLight = new THREE.HemisphereLight(0xbfd8ff, 0x1e1b18, 1.05);
  hemiLight.position.set(0, 50, 0);
  scene.add(hemiLight);

  var dirLight = new THREE.DirectionalLight(0xffdfa8, 1.35);
  dirLight.position.set(18, 36, 22);
  dirLight.castShadow = true;
  if (dirLight.shadow) {
    dirLight.shadow.mapSize.set(2048, 2048);
    dirLight.shadow.bias = -0.0004;
    if (dirLight.shadow.camera) {
      dirLight.shadow.camera.left = -28;
      dirLight.shadow.camera.right = 28;
      dirLight.shadow.camera.top = 28;
      dirLight.shadow.camera.bottom = -28;
      dirLight.shadow.camera.near = 2;
      dirLight.shadow.camera.far = 110;
    }
  }
  scene.add(dirLight);

  var rimLight = new THREE.DirectionalLight(0x38bdf8, 0.75);
  rimLight.position.set(-24, 22, -18);
  scene.add(rimLight);

  var altarLight = new THREE.PointLight(0xff9e3b, 2.4, 24, 1.5);
  altarLight.position.set(0, 4.2, -6.5);
  scene.add(altarLight);

  var westLight = new THREE.PointLight(0x38bdf8, 1.8, 20, 1.5);
  westLight.position.set(-8, 3.8, -2.0);
  scene.add(westLight);

  var eastLight = new THREE.PointLight(0xfbbf24, 1.8, 20, 1.5);
  eastLight.position.set(8, 3.8, -2.0);
  scene.add(eastLight);

  var masterpiece = null;
  var mixers = [];
  var trajectoryCurves = {};
  var trajectoryMeshes = {};
  var activeTrajectoryTime = 0;
  var navmeshDataRef = null;
  var objectsDataRef = null;

  // --- Camera Orbit + WASD state ---
  var orbitTarget = new THREE.Vector3(0, 1.45, -5.8);
  var orbitYaw = 0.04;
  var orbitPitch = 0.04;
  var orbitDist = 6.4;
  var keysDown = Object.create(null);

  function updateFreeCameraFromOrbit() {
    var cosP = Math.cos(orbitPitch);
    camera.position.set(
      orbitTarget.x + Math.sin(orbitYaw) * cosP * orbitDist,
      Math.max(0.6, orbitTarget.y + Math.sin(orbitPitch) * orbitDist),
      orbitTarget.z + Math.cos(orbitYaw) * cosP * orbitDist,
    );
    camera.lookAt(orbitTarget);
  }
  updateFreeCameraFromOrbit();

  // --- Interactive Canvas Controls ---
  var dragging = false;
  var lastPointerX = 0;
  var lastPointerY = 0;

  canvas.addEventListener("pointerdown", function (e) {
    dragging = true;
    lastPointerX = e.clientX;
    lastPointerY = e.clientY;
    if (canvas.setPointerCapture) {
      try {
        canvas.setPointerCapture(e.pointerId);
      } catch (err) {
        /* ignore */
      }
    }
  });

  canvas.addEventListener("pointermove", function (e) {
    if (!dragging) return;
    var dx = e.clientX - lastPointerX;
    var dy = e.clientY - lastPointerY;
    lastPointerX = e.clientX;
    lastPointerY = e.clientY;
    if (state.cameraMode !== "Free") {
      setCameraMode("Free");
    }
    orbitYaw -= dx * 0.0075;
    orbitPitch = Math.max(0.04, Math.min(1.35, orbitPitch + dy * 0.0065));
    updateFreeCameraFromOrbit();
  });

  function stopDrag() {
    dragging = false;
  }
  canvas.addEventListener("pointerup", stopDrag);
  canvas.addEventListener("pointercancel", stopDrag);

  canvas.addEventListener(
    "wheel",
    function (e) {
      e.preventDefault();
      orbitDist = Math.max(3.5, Math.min(55.0, orbitDist + e.deltaY * 0.018));
      if (state.cameraMode === "Free") {
        updateFreeCameraFromOrbit();
      }
    },
    { passive: false },
  );

  window.addEventListener("keydown", function (e) {
    if (e.target && /INPUT|TEXTAREA/.test(e.target.tagName)) return;
    var k = e.key.toLowerCase();
    keysDown[k] = true;
    if (k === "0") setCameraMode("Free");
    else if (k === "1") setCameraMode("Regular");
    else if (k === "2") setCameraMode("Surrounding");
    else if (k === "3") setCameraMode("Reconstruct-Aware");
    else if (k === "4") setCameraMode("Wandering");
    else if (k === "5") setCameraMode("Aerial");
  });

  window.addEventListener("keyup", function (e) {
    var k = e.key.toLowerCase();
    keysDown[k] = false;
  });

  // --- Camera Mode Switcher UI ---
  var camButtons = document.querySelectorAll("[data-cam-mode]");
  function setCameraMode(mode) {
    state.cameraMode = mode;
    activeTrajectoryTime = 0;
    for (var i = 0; i < camButtons.length; i++) {
      var btn = camButtons[i];
      var m = btn.getAttribute("data-cam-mode");
      if (m === mode) {
        btn.classList.add("active");
      } else {
        btn.classList.remove("active");
      }
    }
    // Highlight selected trajectory ribbon
    var modes = Object.keys(trajectoryMeshes);
    for (var j = 0; j < modes.length; j++) {
      var tm = trajectoryMeshes[modes[j]];
      if (!tm || !tm.material) continue;
      if (mode === "Free" || modes[j] === mode) {
        tm.material.opacity = modes[j] === mode ? 0.96 : 0.68;
      } else {
        tm.material.opacity = 0.25;
      }
    }
    if (mode === "Free") {
      updateFreeCameraFromOrbit();
      if (poseReadoutEl) poseReadoutEl.textContent = "Free Orbit + WASD";
    }
  }

  for (var ci = 0; ci < camButtons.length; ci++) {
    (function (btn) {
      btn.addEventListener("click", function () {
        var mode = btn.getAttribute("data-cam-mode") || "Free";
        setCameraMode(mode);
      });
    })(camButtons[ci]);
  }

  // --- Layer Toggle UI ---
  var layerButtons = document.querySelectorAll("[data-layer]");
  function toggleLayer(layerKey) {
    if (!groups[layerKey]) return;
    var next = !state.layers[layerKey];
    state.layers[layerKey] = next;
    groups[layerKey].visible = next;
    for (var i = 0; i < layerButtons.length; i++) {
      var btn = layerButtons[i];
      if (btn.getAttribute("data-layer") === layerKey) {
        btn.classList.toggle("active", next);
        btn.setAttribute("aria-pressed", next ? "true" : "false");
        var chk = btn.querySelector(".mw-chip-check");
        if (chk) chk.textContent = next ? "✓" : "○";
      }
    }
  }

  for (var li = 0; li < layerButtons.length; li++) {
    (function (btn) {
      btn.addEventListener("click", function () {
        var key = btn.getAttribute("data-layer");
        if (key) toggleLayer(key);
      });
    })(layerButtons[li]);
  }

  if (toggleInspectorBtn && inspectorEl) {
    toggleInspectorBtn.addEventListener("click", function () {
      inspectorEl.classList.toggle("hidden");
    });
  }

  // --- Texture helper for 1K ambientCG PBR ---
  var texLoader = new THREE.TextureLoader();
  function loadTiledTexture(url, repeatX, repeatY, isSRGB) {
    var t = texLoader.load(url);
    t.wrapS = THREE.RepeatWrapping;
    t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(repeatX || 1, repeatY || 1);
    if (isSRGB && THREE.sRGBEncoding !== undefined) {
      t.encoding = THREE.sRGBEncoding;
    }
    return t;
  }

  // Ensures any Trimesh CSG/WFC BufferGeometry without UVs gets clean box-projected UVs
  // so tangent-space normal maps never produce NaN black fragments.
  function ensureGeometryUVs(geometry, uvScale) {
    if (!geometry || !geometry.attributes || !geometry.attributes.position) {
      return;
    }
    if (!geometry.attributes.normal) {
      geometry.computeVertexNormals();
    }
    if (geometry.attributes.uv) return;
    var pos = geometry.attributes.position;
    var nor = geometry.attributes.normal;
    var count = pos.count;
    var uvs = new Float32Array(count * 2);
    var scale = uvScale || 0.25;
    for (var i = 0; i < count; i++) {
      var x = pos.getX(i);
      var y = pos.getY(i);
      var z = pos.getZ(i);
      var nx = nor ? Math.abs(nor.getX(i)) : 0;
      var ny = nor ? Math.abs(nor.getY(i)) : 1;
      var nz = nor ? Math.abs(nor.getZ(i)) : 0;
      if (ny >= nx && ny >= nz) {
        uvs[i * 2] = x * scale;
        uvs[i * 2 + 1] = z * scale;
      } else if (nx >= nz) {
        uvs[i * 2] = z * scale;
        uvs[i * 2 + 1] = y * scale;
      } else {
        uvs[i * 2] = x * scale;
        uvs[i * 2 + 1] = y * scale;
      }
    }
    geometry.setAttribute("uv", new THREE.BufferAttribute(uvs, 2));
  }

  // --- Layer 3 Ground + Gothic Cloister Architecture + CSG/WFC + Ash Particles ---
  var ashPoints = null;
  var rockingChairRef = null;
  var chandelierRefs = [];

  function buildLayer3Architecture(manifest) {
    var wl = (manifest && manifest.worldLens) || {};

    // 1. Load REAL 16-bit Polyhaven .hdr Sky & PMREM IBL (kloppenheim_06_puresky_1k.hdr) for hyper-realistic reflections & lighting!
    if (typeof THREE.RGBELoader === "function") {
      try {
        var rgbe = new THREE.RGBELoader();
        rgbe.load(
          "/studio/assets/polyhaven/kloppenheim_06_puresky/kloppenheim_06_puresky_1k.hdr",
          function (hdrTex) {
            hdrTex.mapping = THREE.EquirectangularReflectionMapping;
            var pmrem = new THREE.PMREMGenerator(renderer);
            pmrem.compileEquirectangularShader();
            var envRT = pmrem.fromEquirectangular(hdrTex);
            scene.environment = envRT.texture;
            scene.background = hdrTex;
            scene.fog = new THREE.FogExp2(0x1b2432, 0.008);
          },
        );
      } catch (e) {
        /* fallback sky remains */
      }
    }

    // 2. Natural terrain base + 1K Photogrammetry Stone Sanctuary Plaza
    var earthColor = loadTiledTexture(
      "/studio/assets/ambientcg/Rock035/Rock035_1K-JPG_Color.jpg",
      24,
      24,
      true,
    );
    var earthNormal = loadTiledTexture(
      "/studio/assets/ambientcg/Rock035/Rock035_1K-JPG_NormalGL.jpg",
      24,
      24,
      false,
    );
    var earthRough = loadTiledTexture(
      "/studio/assets/ambientcg/Rock035/Rock035_1K-JPG_Roughness.jpg",
      24,
      24,
      false,
    );
    var groundMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(140, 140, 1, 1),
      new THREE.MeshStandardMaterial({
        map: earthColor,
        normalMap: earthNormal,
        normalScale: new THREE.Vector2(1.4, 1.4),
        roughnessMap: earthRough,
        roughness: 0.85,
        metalness: 0.04,
        color: 0x5c6458,
      }),
    );
    groundMesh.rotation.x = -Math.PI / 2;
    groundMesh.position.y = -0.02;
    groundMesh.receiveShadow = true;
    groups.csg.add(groundMesh);

    // Inner Carved Stone Sanctuary Courtyard Plaza (14m x 16m)
    var plazaColor = loadTiledTexture(
      "/studio/assets/ambientcg/Rock035/Rock035_1K-JPG_Color.jpg",
      6,
      6,
      true,
    );
    var plazaNormal = loadTiledTexture(
      "/studio/assets/ambientcg/Rock035/Rock035_1K-JPG_NormalGL.jpg",
      6,
      6,
      false,
    );
    var plazaRough = loadTiledTexture(
      "/studio/assets/ambientcg/Rock035/Rock035_1K-JPG_Roughness.jpg",
      6,
      6,
      false,
    );
    var plazaMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(13.5, 15.5, 1, 1),
      new THREE.MeshStandardMaterial({
        map: plazaColor,
        normalMap: plazaNormal,
        normalScale: new THREE.Vector2(1.1, 1.1),
        roughnessMap: plazaRough,
        roughness: 0.48,
        metalness: 0.1,
        color: 0x8a929a,
      }),
    );
    plazaMesh.rotation.x = -Math.PI / 2;
    plazaMesh.position.set(0, 0.005, -5.5);
    plazaMesh.receiveShadow = true;
    groups.csg.add(plazaMesh);

    // Center Wooden Sanctuary Runner
    var woodColor = loadTiledTexture(
      "/studio/assets/ambientcg/Wood096/Wood096_1K-JPG_Color.jpg",
      2,
      8,
      true,
    );
    var woodNormal = loadTiledTexture(
      "/studio/assets/ambientcg/Wood096/Wood096_1K-JPG_NormalGL.jpg",
      2,
      8,
      false,
    );
    var aisleMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(2.8, 14.5),
      new THREE.MeshStandardMaterial({
        map: woodColor,
        normalMap: woodNormal,
        normalScale: new THREE.Vector2(1.0, 1.0),
        roughness: 0.42,
        metalness: 0.08,
        color: 0x7c583a,
      }),
    );
    aisleMesh.rotation.x = -Math.PI / 2;
    aisleMesh.position.set(0, 0.014, -5.5);
    aisleMesh.receiveShadow = true;
    groups.csg.add(aisleMesh);

    // 3. 16,000 3D Tapered Wind-Sway Shader Grass Blades around the stone sanctuary plaza!
    if (WorldRealism && typeof WorldRealism.create3DGrassField === "function") {
      try {
        WorldRealism.create3DGrassField(groups.csg, {
          count: 20000,
          spread: 56,
          bladeWidth: 0.08,
          bladeHeight: 0.52,
          excludeFn: function (gx, gz) {
            return Math.abs(gx) < 6.6 && gz > -13.2 && gz < 2.2;
          },
        });
      } catch (e) {
        /* ignore */
      }
    }

    // 4. Photogrammetry Nature & Architectural Perimeter (Boulders, Trees, Ferns, Street Lamps)
    var envScans = [
      {
        url: "/studio/assets/polyhaven/namaqualand_boulders_01/namaqualand_boulders_01_1k.glb",
        x: -8.5,
        y: 0,
        z: -11.5,
        size: 5.2,
        yaw: 0.4,
      },
      {
        url: "/studio/assets/polyhaven/namaqualand_boulders_01/namaqualand_boulders_01_1k.glb",
        x: 8.8,
        y: 0,
        z: -11.0,
        size: 5.5,
        yaw: 2.1,
      },
      {
        url: "/studio/assets/polyhaven/boulder_01/boulder_01_1k.glb",
        x: -7.8,
        y: 0,
        z: -2.0,
        size: 3.4,
        yaw: 1.1,
      },
      {
        url: "/studio/assets/polyhaven/boulder_01/boulder_01_1k.glb",
        x: 8.2,
        y: 0,
        z: -1.8,
        size: 3.6,
        yaw: -0.7,
      },
      {
        url: "/studio/assets/polyhaven/jacaranda_tree/jacaranda_tree_1k.glb",
        x: -9.5,
        y: 0,
        z: -7.5,
        size: 7.5,
        yaw: 0.3,
      },
      {
        url: "/studio/assets/polyhaven/pine_tree_1k.glb",
        x: 9.8,
        y: 0,
        z: -8.2,
        size: 8.2,
        yaw: -0.5,
      },
      {
        url: "/studio/assets/polyhaven/quiver_tree_02/quiver_tree_02_1k.glb",
        x: -7.2,
        y: 0,
        z: -12.5,
        size: 5.0,
        yaw: 0.8,
      },
      {
        url: "/studio/assets/polyhaven/fern_02/fern_02_1k.glb",
        x: -5.8,
        y: 0,
        z: -3.2,
        size: 1.3,
        yaw: 0.2,
      },
      {
        url: "/studio/assets/polyhaven/fern_02/fern_02_1k.glb",
        x: 5.8,
        y: 0,
        z: -3.5,
        size: 1.3,
        yaw: 1.9,
      },
      {
        url: "/studio/assets/polyhaven/shrub_03/shrub_03_1k.glb",
        x: -6.2,
        y: 0,
        z: -9.2,
        size: 1.6,
        yaw: 0.5,
      },
      {
        url: "/studio/assets/polyhaven/shrub_03/shrub_03_1k.glb",
        x: 6.2,
        y: 0,
        z: -9.2,
        size: 1.6,
        yaw: -1.2,
      },
      {
        url: "/studio/assets/polyhaven/street_lamp_01/street_lamp_01_1k.glb",
        x: -5.4,
        y: 0,
        z: -8.8,
        size: 3.4,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/street_lamp_01/street_lamp_01_1k.glb",
        x: 5.4,
        y: 0,
        z: -8.8,
        size: 3.4,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/street_lamp_01/street_lamp_01_1k.glb",
        x: -5.4,
        y: 0,
        z: -2.2,
        size: 3.4,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/street_lamp_01/street_lamp_01_1k.glb",
        x: 5.4,
        y: 0,
        z: -2.2,
        size: 3.4,
        yaw: 0,
      },
    ];
    if (WorldRealism && WorldRealism.loadGlbModel) {
      envScans.forEach(function (es) {
        WorldRealism.loadGlbModel(
          es.url,
          function (mr) {
            if (!mr) return;
            var h = new THREE.Group();
            h.position.set(es.x, es.y, es.z);
            h.rotation.y = es.yaw || 0;
            h.add(mr);
            groups.csg.add(h);
          },
          { targetLength: es.size },
        );
      });
    }

    // Load CSG & WFC meshes cleanly behind the far cliff horizon (z = -34) so they remain inspectable without blocking the photogrammetry sanctuary
    var gltfLoader = new THREE.GLTFLoader();
    var csgUrl =
      wl.collisionProxyGlbUrl ||
      "/studio/assets/custom/metaworld2/collision_proxy.glb";
    var wfcUrl =
      wl.wfcCourtyardGlbUrl ||
      "/studio/assets/custom/metaworld2/wfc_courtyard_addon.glb";
    var csgDone = false;
    var wfcDone = false;
    function updateCsgStatus() {
      if (csgDone && wfcDone) {
        state.csgLoaded = true;
        state.wfcLoaded = true;
        if (statCsgEl) statCsgEl.textContent = "4 Walls/8 CSG + 6×6 WFC";
        checkAllReady();
      }
    }
    gltfLoader.load(
      csgUrl,
      function (gltf) {
        var root = gltf.scene || (gltf.scenes && gltf.scenes[0]);
        if (root) {
          root.position.set(0, -12.0, -45.0);
          groups.csg.add(root);
        }
        csgDone = true;
        updateCsgStatus();
      },
      undefined,
      function () {
        csgDone = true;
        updateCsgStatus();
      },
    );
    gltfLoader.load(
      wfcUrl,
      function (gltf) {
        var root = gltf.scene || (gltf.scenes && gltf.scenes[0]);
        if (root) {
          root.position.set(0, -12.0, -48.0);
          groups.csg.add(root);
        }
        wfcDone = true;
        updateCsgStatus();
      },
      undefined,
      function () {
        wfcDone = true;
        updateCsgStatus();
      },
    );

    // Soft radial golden fireflies / embers drifting in the air
    var cv = document.createElement("canvas");
    cv.width = 64;
    cv.height = 64;
    var g = cv.getContext("2d");
    var grad = g.createRadialGradient(32, 32, 1, 32, 32, 30);
    grad.addColorStop(0, "rgba(255, 232, 185, 1)");
    grad.addColorStop(0.4, "rgba(255, 190, 110, 0.45)");
    grad.addColorStop(1, "rgba(0, 0, 0, 0)");
    g.fillStyle = grad;
    g.fillRect(0, 0, 64, 64);
    var dotTex = new THREE.CanvasTexture(cv);
    var pGeo = new THREE.BufferGeometry();
    var pCount = 320;
    var pPos = new Float32Array(pCount * 3);
    for (var pi = 0; pi < pCount; pi++) {
      pPos[pi * 3] = (Math.random() - 0.5) * 20;
      pPos[pi * 3 + 1] = 0.4 + Math.random() * 4.5;
      pPos[pi * 3 + 2] = -13 + Math.random() * 14;
    }
    pGeo.setAttribute("position", new THREE.BufferAttribute(pPos, 3));
    ashPoints = new THREE.Points(
      pGeo,
      new THREE.PointsMaterial({
        size: 0.12,
        map: dotTex,
        transparent: true,
        opacity: 0.78,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    groups.csg.add(ashPoints);
  }

  // --- Layer 2 VGGT-1B Neural 3D Surface Mesh Loader ---
  function buildLayer2Vggt(manifest) {
    var wl = (manifest && manifest.worldLens) || {};
    var vggtUrl =
      wl.vggtSurfaceGlbUrl ||
      "/studio/assets/custom/metaworld2/vggt_surface.glb";
    var loader = new THREE.GLTFLoader();
    loader.load(
      vggtUrl,
      function (gltf) {
        var root = gltf.scene || (gltf.scenes && gltf.scenes[0]);
        if (root) {
          root.position.set(0, 1.5, -28.0);
          root.scale.set(1.25, 0.75, 0.95);
          root.traverse(function (node) {
            if (node && node.isMesh) {
              node.castShadow = false;
              node.receiveShadow = true;
              if (node.material) {
                node.material.vertexColors = true;
                node.material.roughness = 0.82;
                node.material.metalness = 0.08;
                node.material.side = THREE.DoubleSide;
              }
            }
          });
          groups.vggt.add(root);
        }
        state.vggtMeshLoaded = true;
        if (statVggtEl) statVggtEl.textContent = "21,590 Tris";
        checkAllReady();
      },
      undefined,
      function (err) {
        state.errors.push("VGGT GLB error: " + String(err));
      },
    );
  }

  // --- Layer 1 3D Gaussian Splat Cloud Loader ---
  function buildLayer1Splats(manifest) {
    var wl = (manifest && manifest.worldLens) || {};
    var splatUrl =
      wl.gaussianSplatUrl ||
      "/studio/assets/custom/metaworld2/world_3dgs.splat";
    if (!WorldRealism || typeof WorldRealism.loadGaussianSplat !== "function") {
      state.errors.push("WorldRealism.loadGaussianSplat missing");
      return;
    }
    WorldRealism.loadGaussianSplat(splatUrl, {
      pointScale: 520.0,
      opacity: 0.92,
      depthWrite: false,
      position: [0, 3.2, -26.0],
      scale: 0.52,
    })
      .then(function (points) {
        groups.splats.add(points);
        var count =
          (points && points.userData && points.userData.splatCount) || 0;
        state.splats = count;
        if (statSplatsEl) {
          statSplatsEl.textContent = count.toLocaleString() + " splats";
        }
        checkAllReady();
      })
      .catch(function (err) {
        state.errors.push("3DGS load error: " + String(err));
      });
  }

  // --- Layer 4 SAM 3.1 Semantic 3D Landmarks (Real Photogrammetry + Rigged GLBs) ---
  var FALLBACK_LANDMARK_GLBS = [
    "/studio/assets/polyhaven/large_castle_door/large_castle_door_1k.glb",
    "/studio/assets/polyhaven/GothicCabinet_01/GothicCabinet_01_1k.glb",
    "/studio/assets/polyhaven/SchoolDesk_01/SchoolDesk_01_1k.glb",
    "/studio/assets/polyhaven/Lantern_01/Lantern_01_1k.glb",
    "/studio/live-preview/assets/agatha.glb",
  ];

  function buildLayer4Landmarks(objectsPayload) {
    var objs = (objectsPayload && objectsPayload.objects) || [];
    var dracoLoader = null;
    if (typeof THREE.DRACOLoader === "function") {
      try {
        dracoLoader = new THREE.DRACOLoader();
        dracoLoader.setDecoderPath("/studio/vendor/");
      } catch (e) {
        dracoLoader = null;
      }
    }

    // Additional rich Polyhaven photogrammetry sanctuary & cloister furnishing
    var extraFurnishings = [
      {
        url: "/studio/assets/polyhaven/WoodenTable_01/WoodenTable_01_1k.glb",
        x: 0,
        y: 0,
        z: -8.6,
        size: 2.1,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/brass_candleholders/brass_candleholders_1k.glb",
        x: -0.55,
        y: 0.82,
        z: -8.6,
        size: 0.42,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/brass_candleholders/brass_candleholders_1k.glb",
        x: 0.55,
        y: 0.82,
        z: -8.6,
        size: 0.42,
        yaw: 0.4,
      },
      {
        url: "/studio/assets/polyhaven/painted_wooden_bench/painted_wooden_bench_1k.glb",
        x: -2.4,
        y: 0,
        z: -5.2,
        size: 2.2,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/painted_wooden_bench/painted_wooden_bench_1k.glb",
        x: 2.4,
        y: 0,
        z: -5.2,
        size: 2.2,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/painted_wooden_bench/painted_wooden_bench_1k.glb",
        x: -2.4,
        y: 0,
        z: -2.6,
        size: 2.2,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/painted_wooden_bench/painted_wooden_bench_1k.glb",
        x: 2.4,
        y: 0,
        z: -2.6,
        size: 2.2,
        yaw: 0,
      },
      {
        url: "/studio/assets/polyhaven/wooden_bookshelf_worn/wooden_bookshelf_worn_1k.glb",
        x: -4.6,
        y: 0,
        z: -7.5,
        size: 2.2,
        yaw: 1.57,
      },
      {
        url: "/studio/assets/polyhaven/vintage_grandfather_clock_01/vintage_grandfather_clock_01_1k.glb",
        x: -4.6,
        y: 0,
        z: -9.6,
        size: 2.15,
        yaw: 1.3,
      },
      {
        url: "/studio/assets/polyhaven/Rockingchair_01/Rockingchair_01_1k.glb",
        x: -3.6,
        y: 0,
        z: -6.2,
        size: 1.05,
        yaw: 0.8,
        isRocker: true,
      },
      {
        url: "/studio/assets/polyhaven/treasure_chest/treasure_chest_1k.glb",
        x: 4.3,
        y: 0,
        z: -7.8,
        size: 1.0,
        yaw: -1.57,
      },
      {
        url: "/studio/assets/polyhaven/SchoolChair_01/SchoolChair_01_1k.glb",
        x: 3.8,
        y: 0,
        z: -3.2,
        size: 0.85,
        yaw: 3.14,
      },
    ];
    extraFurnishings.forEach(function (ef) {
      if (!WorldRealism || !WorldRealism.loadGlbModel) return;
      WorldRealism.loadGlbModel(
        ef.url,
        function (mr) {
          if (!mr) return;
          var h = new THREE.Group();
          h.position.set(ef.x, ef.y, ef.z);
          h.rotation.y = ef.yaw || 0;
          h.add(mr);
          groups.landmarks.add(h);
          if (ef.isRocker) rockingChairRef = h;
          if (ef.y === 0 && masterpiece && masterpiece.makeContactShadow) {
            var cs = masterpiece.makeContactShadow(
              ef.size * 0.95,
              ef.size * 0.95,
              0.58,
            );
            if (cs) {
              cs.position.set(ef.x, 0.02, ef.z);
              groups.landmarks.add(cs);
            }
          }
        },
        { targetLength: ef.size, dracoLoader: dracoLoader },
      );
    });

    objs.forEach(function (lm, idx) {
      var pos = lm.position || [0, 0, 0];
      var wx = Number(pos[0]) || 0;
      var wy = Number(pos[1]) || 0;
      var wz = Number(pos[2]) || 0;
      var radius = Number(lm.radius) || 2.0;
      var height = Number(lm.height) || 3.8;
      var standoff = Number(lm.standoffRadius) || radius + 3.2;
      var glbUrl =
        lm.glbUrl ||
        lm.modelUrl ||
        FALLBACK_LANDMARK_GLBS[idx % FALLBACK_LANDMARK_GLBS.length];
      var targetSize = Number(lm.targetSize) || 3.0;
      var yawRad = ((Number(lm.yawDeg) || 0) * Math.PI) / 180.0;

      // 3D Semantic Wireframe Bounding Cylinder + Standoff Ring in `groups.bboxes`
      var wireColors = [0x38bdf8, 0xfbbf24, 0xa855f7, 0x4ade80, 0xf43f5e];
      var wireColor = wireColors[idx % wireColors.length];

      var boxGeo = new THREE.BoxGeometry(radius * 1.45, height, radius * 1.45);
      var edgesGeo = new THREE.EdgesGeometry(boxGeo);
      var wireBox = new THREE.LineSegments(
        edgesGeo,
        new THREE.LineBasicMaterial({
          color: wireColor,
          transparent: true,
          opacity: 0.72,
        }),
      );
      wireBox.position.set(wx, wy + height * 0.5, wz);
      groups.bboxes.add(wireBox);

      var ringGeo = new THREE.RingGeometry(
        standoff - 0.08,
        standoff + 0.08,
        48,
      );
      var ringMat = new THREE.MeshBasicMaterial({
        color: wireColor,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 0.42,
      });
      var ringMesh = new THREE.Mesh(ringGeo, ringMat);
      ringMesh.rotation.x = -Math.PI / 2;
      ringMesh.position.set(wx, 0.05, wz);
      groups.bboxes.add(ringMesh);

      // Contact shadow under each landmark
      if (masterpiece && typeof masterpiece.makeContactShadow === "function") {
        var cShadow = masterpiece.makeContactShadow(
          radius * 2.1,
          radius * 2.1,
          0.65,
        );
        if (cShadow) {
          cShadow.position.set(wx, 0.03, wz);
          groups.landmarks.add(cShadow);
        }
      }

      // Load real photogrammetry / rigged .glb model
      var gltfLoader = new THREE.GLTFLoader();
      if (dracoLoader) {
        try {
          gltfLoader.setDRACOLoader(dracoLoader);
        } catch (e) {
          /* ignore */
        }
      }
      gltfLoader.load(
        glbUrl,
        function (gltf) {
          var modelRoot = gltf.scene || (gltf.scenes && gltf.scenes[0]);
          if (modelRoot) {
            if (
              WorldRealism &&
              typeof WorldRealism.normalizeToSize === "function"
            ) {
              WorldRealism.normalizeToSize(modelRoot, targetSize);
            }
            var holder = new THREE.Group();
            holder.name = lm.id || "landmark_" + idx;
            holder.position.set(wx, wy, wz);
            holder.rotation.y = yawRad;
            holder.add(modelRoot);

            modelRoot.traverse(function (node) {
              if (node && node.isMesh) {
                node.castShadow = true;
                node.receiveShadow = true;
              }
            });

            if (
              gltf.animations &&
              gltf.animations.length > 0 &&
              typeof THREE.AnimationMixer === "function"
            ) {
              var mixer = new THREE.AnimationMixer(modelRoot);
              var action = mixer.clipAction(gltf.animations[0]);
              action.play();
              mixers.push(mixer);
            }

            groups.landmarks.add(holder);
          }
          state.landmarksLoaded += 1;
          if (statLandmarksEl) {
            statLandmarksEl.textContent =
              state.landmarksLoaded + "/" + objs.length;
          }
          checkAllReady();
        },
        undefined,
        function (err) {
          state.errors.push(
            "Landmark GLB load error (" + glbUrl + "): " + String(err),
          );
        },
      );
    });
  }

  // --- Layer 5 WorldNav 24x24m NavMesh & 5 Trajectory Spline Ribbons ---
  var TRAJ_COLORS = {
    Regular: 0x38bdf8,
    Surrounding: 0xfbbf24,
    "Reconstruct-Aware": 0xa855f7,
    Wandering: 0x4ade80,
    Aerial: 0xf43f5e,
  };

  function buildLayer5Navmesh(navData) {
    if (!navData) return;
    var bound = Number(navData.worldBound) || 36.0;
    var cellSize = Number(navData.cellSize) || 3.0;

    // Subtle courtyard NavMesh grid helper on ground
    var gridHelper = new THREE.GridHelper(
      bound * 2,
      Math.round((bound * 2) / cellSize),
      0x38bdf8,
      0x1e293b,
    );
    gridHelper.position.y = 0.04;
    if (gridHelper.material) {
      gridHelper.material.transparent = true;
      gridHelper.material.opacity = 0.32;
    }
    groups.navmesh.add(gridHelper);

    // Spawn beacon at (0, 0, 0)
    var spawnGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.14, 24);
    var spawnMat = new THREE.MeshBasicMaterial({ color: 0x4ade80 });
    var spawnBeacon = new THREE.Mesh(spawnGeo, spawnMat);
    spawnBeacon.position.set(0, 0.08, 0);
    groups.navmesh.add(spawnBeacon);

    var trajs = navData.trajectories || {};
    var modeNames = Object.keys(trajs);
    var builtTrajectories = 0;

    modeNames.forEach(function (modeName) {
      var waypoints = trajs[modeName] || [];
      if (waypoints.length < 2) return;

      var posPts = [];
      var lookPts = [];
      for (var i = 0; i < waypoints.length; i++) {
        var p = waypoints[i].position || [0, 1.7, 0];
        var l = waypoints[i].lookAt || [0, 1.6, -5];
        posPts.push(new THREE.Vector3(p[0], p[1], p[2]));
        lookPts.push(new THREE.Vector3(l[0], l[1], l[2]));
      }

      var posCurve = new THREE.CatmullRomCurve3(posPts, true);
      var lookCurve = new THREE.CatmullRomCurve3(lookPts, true);
      trajectoryCurves[modeName] = {
        posCurve: posCurve,
        lookCurve: lookCurve,
        waypoints: waypoints,
      };

      var col = TRAJ_COLORS[modeName] || 0x38bdf8;
      var tubeGeo = new THREE.TubeGeometry(posCurve, 72, 0.11, 8, true);
      var tubeMat = new THREE.MeshBasicMaterial({
        color: col,
        transparent: true,
        opacity: 0.72,
      });
      var tubeMesh = new THREE.Mesh(tubeGeo, tubeMat);
      tubeMesh.name = "TrajectoryRibbon_" + modeName;
      groups.navmesh.add(tubeMesh);
      trajectoryMeshes[modeName] = tubeMesh;

      // Add waypoint nodes along the ribbon
      var nodeGeo = new THREE.SphereGeometry(0.22, 10, 10);
      var nodeMat = new THREE.MeshBasicMaterial({ color: col });
      for (var w = 0; w < posPts.length; w++) {
        var nodeMesh = new THREE.Mesh(nodeGeo, nodeMat);
        nodeMesh.position.copy(posPts[w]);
        groups.navmesh.add(nodeMesh);
      }

      builtTrajectories += 1;
    });

    state.trajectories = builtTrajectories;
    if (statBfsEl && navData.bfsVerification) {
      statBfsEl.textContent =
        navData.walkableCells + "/" + navData.walkableCells + " (100%)";
    }
    checkAllReady();
  }

  // --- Stage II NavMesh Minimap Renderer ---
  function drawNavmeshMinimap() {
    if (!minimapCanvas || !navmeshDataRef) return;
    var ctx = minimapCanvas.getContext("2d");
    if (!ctx) return;
    var w = minimapCanvas.width;
    var h = minimapCanvas.height;
    var bound = Number(navmeshDataRef.worldBound) || 36.0;

    ctx.fillStyle = "#050811";
    ctx.fillRect(0, 0, w, h);

    function toMiniX(wx) {
      return ((wx + bound) / (bound * 2)) * (w - 16) + 8;
    }
    function toMiniY(wz) {
      return ((wz + bound) / (bound * 2)) * (h - 10) + 5;
    }

    // Subtle grid lines
    ctx.strokeStyle = "rgba(56, 189, 248, 0.12)";
    ctx.lineWidth = 1;
    for (var gx = -bound; gx <= bound; gx += 9) {
      var mx = toMiniX(gx);
      ctx.beginPath();
      ctx.moveTo(mx, 2);
      ctx.lineTo(mx, h - 2);
      ctx.stroke();
    }

    // Draw trajectory polylines
    var trajs = navmeshDataRef.trajectories || {};
    var colorHex = {
      Regular: "#38bdf8",
      Surrounding: "#fbbf24",
      "Reconstruct-Aware": "#a855f7",
      Wandering: "#4ade80",
      Aerial: "#f43f5e",
    };
    Object.keys(trajs).forEach(function (modeName) {
      var pts = trajs[modeName] || [];
      if (!pts.length) return;
      ctx.strokeStyle = colorHex[modeName] || "#38bdf8";
      ctx.lineWidth = state.cameraMode === modeName ? 2.0 : 1.0;
      ctx.beginPath();
      pts.forEach(function (wp, i) {
        var px = toMiniX(wp.position[0]);
        var py = toMiniY(wp.position[2]);
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      });
      ctx.closePath();
      ctx.stroke();
    });

    // Draw 5 SAM 3.1 landmarks
    if (objectsDataRef && Array.isArray(objectsDataRef.objects)) {
      objectsDataRef.objects.forEach(function (lm) {
        var lx = toMiniX(lm.position[0]);
        var ly = toMiniY(lm.position[2]);
        ctx.fillStyle = "#fbbf24";
        ctx.beginPath();
        ctx.arc(lx, ly, 3.2, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    // Draw live camera position dot
    var camX = toMiniX(camera.position.x);
    var camY = toMiniY(camera.position.z);
    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.arc(camX, camY, 3.8, 0, Math.PI * 2);
    ctx.fill();
  }

  // --- Boot Pipeline: Fetch Manifest, NavMesh, and Objects JSON ---
  Promise.all([
    fetch("/studio/assets/custom/metaworld2/metaworld2_manifest.json").then(
      function (r) {
        if (!r.ok) throw new Error("Manifest HTTP " + r.status);
        return r.json();
      },
    ),
    fetch("/studio/assets/custom/metaworld2/navmesh.json").then(function (r) {
      if (!r.ok) throw new Error("NavMesh HTTP " + r.status);
      return r.json();
    }),
    fetch("/studio/assets/custom/metaworld2/objects.json").then(function (r) {
      if (!r.ok) throw new Error("Objects HTTP " + r.status);
      return r.json();
    }),
  ])
    .then(function (results) {
      var manifest = results[0];
      var navmeshData = results[1];
      var objectsData = results[2];
      navmeshDataRef = navmeshData;
      objectsDataRef = objectsData;

      // Enable WorldRealism Masterpiece Rendering (PMREM IBL + Bloom + Grade + Contact Shadow)
      var mpOpts =
        (manifest &&
          manifest.worldLens &&
          manifest.worldLens.masterpieceOptions) ||
        {};
      if (
        WorldRealism &&
        typeof WorldRealism.enableMasterpieceRendering === "function"
      ) {
        masterpiece = WorldRealism.enableMasterpieceRendering(
          renderer,
          scene,
          camera,
          mpOpts,
        );
      }

      // Equirectangular Skybox Dome from Stage I Panorama Seed
      var panoUrl =
        (manifest &&
          manifest.worldLens &&
          manifest.worldLens.skyboxPanoramaUrl) ||
        "/studio/assets/custom/metaworld2/stage1_seed_pano.png";
      texLoader.load(panoUrl, function (panoTex) {
        panoTex.mapping = THREE.EquirectangularReflectionMapping;
        if (THREE.sRGBEncoding !== undefined) {
          panoTex.encoding = THREE.sRGBEncoding;
        }
        var skyGeo = new THREE.SphereGeometry(240, 48, 24);
        var skyMat = new THREE.MeshBasicMaterial({
          map: panoTex,
          side: THREE.BackSide,
          depthWrite: false,
          fog: false,
        });
        var skyDome = new THREE.Mesh(skyGeo, skyMat);
        skyDome.name = "Stage1_Equirectangular_Skybox";
        /* 16-bit .hdr RGBELoader sky active */
      });

      // Populate Stage III / IV Inspector telemetry from manifest
      var s3 =
        (manifest && manifest.stages && manifest.stages.stage3_worldstereo) ||
        {};
      var s4 =
        (manifest && manifest.stages && manifest.stages.stage4_worldmirror) ||
        {};
      state.depthBackend = s3.depthBackend || "";
      state.ransacAlignment = s3.ransacAlignment || null;
      if (depthBadgeEl && s3.depthBackend) {
        depthBadgeEl.textContent = s3.depthBackend;
      }
      if (metaS3SubEl && s3.ransacAlignment) {
        var ra = s3.ransacAlignment;
        metaS3SubEl.textContent =
          "RANSAC γ=" +
          ra.gamma +
          ", β=" +
          ra.beta +
          " (" +
          Math.round((ra.inlierRatio || 0) * 100) +
          "% inliers, RMSE " +
          ra.residualRmse +
          ")";
      }
      if (
        metaS4El &&
        s4.gaussianSplatCloud &&
        s4.vggtSurfaceMesh &&
        s4.collisionProxyGlb
      ) {
        metaS4El.innerHTML =
          s4.gaussianSplatCloud.keptSplats.toLocaleString() +
          " MaskGaussian 3DGS · VGGT-1B " +
          s4.vggtSurfaceMesh.faces.toLocaleString() +
          " Tris" +
          '<span class="sub">SceneScript ' +
          s4.collisionProxyGlb.walls +
          " Walls / " +
          s4.collisionProxyGlb.csgBooleanOpenings +
          " CSG Openings + " +
          (s4.wfcCourtyardGlb ? s4.wfcCourtyardGlb.grid : "6×6") +
          " WFC</span>";
      }

      // Mount all 5 3D layers
      buildLayer1Splats(manifest);
      buildLayer2Vggt(manifest);
      buildLayer3Architecture(manifest);
      buildLayer4Landmarks(objectsData);
      buildLayer5Navmesh(navmeshData);
      drawNavmeshMinimap();
    })
    .catch(function (err) {
      state.errors.push("Pipeline init error: " + String(err));
      setStatus("Error loading MetaWorld 2.0 manifest: " + String(err));
    });

  // --- Resize handler ---
  window.addEventListener("resize", function () {
    var w = canvas.clientWidth || window.innerWidth;
    var h = Math.max(1, canvas.clientHeight || window.innerHeight - 46);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
    if (masterpiece && typeof masterpiece.setSize === "function") {
      masterpiece.setSize(w, h);
    }
  });

  // --- Animation Loop ---
  var lastTime = performance.now();
  var tmpPos = new THREE.Vector3();
  var tmpLook = new THREE.Vector3();
  var frameCounter = 0;

  function animate(now) {
    requestAnimationFrame(animate);
    var dt = Math.min(0.05, Math.max(0.001, (now - lastTime) * 0.001));
    lastTime = now;
    frameCounter++;

    // Update any GLB AnimationMixers (e.g. Mother Agatha 20-bone rig)
    for (var m = 0; m < mixers.length; m++) {
      try {
        mixers[m].update(dt);
      } catch (e) {
        /* ignore */
      }
    }

    if (state.cameraMode === "Free") {
      // WASD / Arrow fly movement in Free mode
      var moveSpeed = (keysDown["shift"] ? 18.0 : 9.5) * dt;
      var forwardX = -Math.sin(orbitYaw);
      var forwardZ = -Math.cos(orbitYaw);
      var rightX = Math.cos(orbitYaw);
      var rightZ = -Math.sin(orbitYaw);

      if (keysDown["w"] || keysDown["arrowup"]) {
        orbitTarget.x += forwardX * moveSpeed;
        orbitTarget.z += forwardZ * moveSpeed;
        updateFreeCameraFromOrbit();
      }
      if (keysDown["s"] || keysDown["arrowdown"]) {
        orbitTarget.x -= forwardX * moveSpeed;
        orbitTarget.z -= forwardZ * moveSpeed;
        updateFreeCameraFromOrbit();
      }
      if (keysDown["a"] || keysDown["arrowleft"]) {
        orbitTarget.x -= rightX * moveSpeed;
        orbitTarget.z -= rightZ * moveSpeed;
        updateFreeCameraFromOrbit();
      }
      if (keysDown["d"] || keysDown["arrowright"]) {
        orbitTarget.x += rightX * moveSpeed;
        orbitTarget.z += rightZ * moveSpeed;
        updateFreeCameraFromOrbit();
      }
      if (keysDown["e"] || keysDown[" "]) {
        orbitTarget.y = Math.min(18.0, orbitTarget.y + moveSpeed * 0.6);
        updateFreeCameraFromOrbit();
      }
      if (keysDown["q"]) {
        orbitTarget.y = Math.max(0.5, orbitTarget.y - moveSpeed * 0.6);
        updateFreeCameraFromOrbit();
      }
    } else if (trajectoryCurves[state.cameraMode]) {
      // Smooth spline interpolation along selected WorldNav trajectory mode
      var tc = trajectoryCurves[state.cameraMode];
      activeTrajectoryTime = (activeTrajectoryTime + dt * 0.055) % 1.0;
      tc.posCurve.getPointAt(activeTrajectoryTime, tmpPos);
      tc.lookCurve.getPointAt(activeTrajectoryTime, tmpLook);
      camera.position.lerp(tmpPos, 0.18);
      camera.lookAt(tmpLook);

      if (poseReadoutEl && frameCounter % 6 === 0) {
        var wpCount = tc.waypoints ? tc.waypoints.length : 1;
        var stepIdx = Math.floor(activeTrajectoryTime * wpCount);
        poseReadoutEl.textContent =
          state.cameraMode +
          " · step " +
          stepIdx +
          "/" +
          wpCount +
          " [" +
          camera.position.x.toFixed(1) +
          ", " +
          camera.position.y.toFixed(1) +
          ", " +
          camera.position.z.toFixed(1) +
          "]";
      }
    }

    if (frameCounter % 10 === 0) {
      drawNavmeshMinimap();
    }

    if (masterpiece && typeof masterpiece.render === "function") {
      masterpiece.render();
    } else {
      renderer.render(scene, camera);
    }
  }

  requestAnimationFrame(animate);

  window.metaWorldViewer = {
    state: state,
    scene: scene,
    camera: camera,
    renderer: renderer,
    groups: groups,
    setCameraMode: setCameraMode,
    toggleLayer: toggleLayer,
  };
})();
